/**
 * Offline help knowledge base (owner: assist area). Every article exists in English and Urdu (Urdu script) and has
 * Roman-Urdu / English / Urdu keywords for search. Articles describe screens and buttons that exist in DT Solar Pro.
 */
export interface Bi {
  en: string
  ur: string
}

export interface HelpArticle {
  id: string
  category: HelpCategory
  title: Bi
  summary: Bi
  /** Where to find it in the app */
  path: Bi
  /** In-app route to open the screen (optional) */
  route?: string
  steps: { en: string[]; ur: string[] }
  keywords: string[]
  related: string[]
}

export type HelpCategory = 'sales' | 'purchases' | 'parties' | 'inventory' | 'projects' | 'accounts' | 'closing' | 'reports' | 'printing' | 'whatsapp' | 'data' | 'security' | 'firms' | 'license' | 'support' | 'troubleshooting'

